package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaFractionNamesTest {
 @Test public void actualGradeSupplyOnlyUsesNamedFractions(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");assertFalse(GlobalCurriculum.pack(p).inGrade("fractionNamePicture",1));for(int grade:List.of(2,3)){Set<String> allowed=grade==2?Set.of("1/2","1/4"):Set.of("1/2","1/4","3/4","1/3");assertTrue(GlobalCurriculum.pack(p).inGrade("fractionNamePicture",grade));for(String id:List.of("fractionNamePicture","fractionPart")){Generator g=new Generator(new Random(210+grade));CurriculumLimits limits=GlobalCurriculum.limits(p.educationSystem,id,grade);Set<String> seen=new HashSet<>();List<String> recent=new ArrayList<>();for(int i=0;i<80;i++){Question q=g.next(id,recent,false,limits);assertTrue(limits.allows(q));if(q.diagram!=null&&q.diagram.type.equals("fractionSelection")){String pair=Integer.bitCount((int)q.diagram.values[1])+"/"+(int)q.diagram.values[0];assertTrue(pair,allowed.contains(pair));seen.add(pair);}else{assertTrue(q.expression,allowed.contains(q.expression));seen.add(q.expression);}assertFalse(q.choiceLabels.containsKey("2/3"));assertFalse(q.choiceLabels.containsKey("2/4"));recent.add(q.signature());if(recent.size()>3)recent.remove(0);if(id.equals("fractionNamePicture"))assertNotNull(HelpPlan.forQuestion(q));}assertEquals(allowed,seen);}}}
 @Test public void gradeThreeRejectsUnlistedPartsWithoutChangingGradeFour(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");for(String value:List.of("2/3","2/4")){Question q=new Question("fractionPart","",value,value);assertFalse(GlobalCurriculum.limits(p.educationSystem,"fractionPart",3).allows(q));assertTrue(GlobalCurriculum.limits(p.educationSystem,"fractionPart",4).allows(q));}}
}
